// Purpose-only observation of an original legacy SQL-owned file. This is not an
// immutable registry/native creator/WriterLease/serving/import authority.
struct SqliteOriginalLegacyAsset{id:String,space:String,page:String,path:String,mime:String,length:u64,sha:String,held:File,stamp:PhysicalStamp,proofs:Vec<crate::spaces::published_source::SourceProof>}
async fn sqlite_capture_legacy(source:&mut StoppedVerificationSource<'_>,auth:&crate::auth::middleware::AuthUser,id:&str,space:&str,page:&str,path:&str,size:i64)->anyhow::Result<SqliteOriginalLegacyAsset>{
 use sqlx::Row;source.fence().await?;let(binding,absence)=crate::storage::attachment_versions::capture_current_asset(&source.root.absolute,source.conn,id).await.map_err(|e|anyhow::anyhow!("Original legacy registry unavailable: {e}"))?;anyhow::ensure!(binding.is_none(),"Registered/partial registry cannot become legacy ownership");let row=sqlx::query("SELECT a.*,s.slug AS original_space_slug FROM attachments a JOIN spaces s ON s.id=a.space_id WHERE a.id=$1").bind(id).fetch_one(&mut *source.conn).await?;let filename:String=row.try_get("filename")?;let mime:String=row.try_get("mime_type")?;anyhow::ensure!(!mime.is_empty()&&mime.len()<=255&&!mime.contains(&['\r','\n'][..]),"Original legacy media type invalid");let slug:String=row.try_get("original_space_slug")?;let selected_space:String=row.try_get("space_id")?;let selected_page:String=row.try_get("document_id")?;let selected_path:String=row.try_get("storage_path")?;anyhow::ensure!(selected_space==space&&selected_page==page&&selected_path==path&&row.try_get::<i64,_>("size_bytes")?==size,"Original legacy SQL association differs");sqlite_legacy_path(id,&slug,page,&filename,path)?;
 let alias_query="SELECT * FROM move_asset_path_aliases WHERE asset_kind='attachment' AND (old_path=$1 OR asset_id=$2)";let aliases=crate::spaces::document_deletion::rows(source.conn,alias_query,&[path,id]).await.map_err(|e|anyhow::anyhow!(e))?;anyhow::ensure!(aliases.is_empty(),"Legacy alias requires separately qualified original ownership");let access=crate::spaces::shared_pages::asset_view(source.conn,auth,space,page).await.map_err(|e|anyhow::anyhow!("Original legacy routine view unavailable:{e:?}"))?;let mut proofs=crate::spaces::published_source::capture_source(source.conn,auth,space,page,&access.ancestor_ids).await.map_err(|e|anyhow::anyhow!("Original legacy audience closure unavailable:{e:?}"))?;proofs.push(absence);proofs.push(crate::spaces::published_source::SourceProof{query:alias_query.into(),parameters:vec![path.into(),id.into()],rows:aliases});for(query,value)in [("SELECT * FROM attachments WHERE id=$1",id),("SELECT * FROM spaces WHERE id=$1",space)]{proofs.push(crate::spaces::published_source::SourceProof{query:query.into(),parameters:vec![value.into()],rows:crate::spaces::document_deletion::rows(source.conn,query,&[value]).await.map_err(|e|anyhow::anyhow!(e))?});}
 let length=u64::try_from(size)?;anyhow::ensure!(length<=100*1024*1024,"Original legacy binary exceeds100MiB");let(file,stamp,_)=source.inventory.files.get(path).context("Original legacy file absent from held inventory")?;anyhow::ensure!(stamp.length==length,"Original legacy SQL/inventory length differs");let result=SqliteOriginalLegacyAsset{id:id.into(),space:space.into(),page:page.into(),path:path.into(),mime,length,sha:hash_file(file,length)?,held:file.try_clone()?,stamp:stamp.clone(),proofs};result.fence(source).await?;Ok(result)
}
fn sqlite_legacy_path(id:&str,slug:&str,page:&str,filename:&str,path:&str)->anyhow::Result<()>{anyhow::ensure!(uuid::Uuid::parse_str(id).ok().is_some_and(|v|v.to_string()==id),"Original legacy ID must be canonical UUID");for part in [slug,page]{anyhow::ensure!(!part.is_empty()&&part.len()<=200&&part.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'||b==b'_'),"Original legacy namespace unsafe");}let extension=filename.strip_prefix(&format!("{id}.")).context("Legacy filename differs from exact original ID")?;anyhow::ensure!(!extension.is_empty()&&extension.len()<=16&&extension.bytes().all(|b|b.is_ascii_alphanumeric())&&path==format!("spaces/{slug}/attachments/{page}/{filename}")&&valid_relative(path),"Original legacy path/filename not exact canonical ownership");Ok(())}
impl SqliteOriginalLegacyAsset{async fn fence(&self,source:&mut StoppedVerificationSource<'_>)->anyhow::Result<()>{source.fence().await?;let current=source.root.leaf(&self.path)?;anyhow::ensure!(physical_stamp(&self.held)?==self.stamp&&physical_stamp(&current)?==self.stamp&&hash_file(&self.held,self.length)?==self.sha&&hash_file(&current,self.length)?==self.sha,"Original legacy file bytes/inode exchanged");crate::spaces::published_source::verify_source(source.conn,&self.proofs).await.map_err(|e|anyhow::anyhow!("Original legacy SQL/audience differs:{e:?}"))?;Ok(())}}
async fn sqlite_legacy_download(client:&reqwest::Client,address:std::net::SocketAddr,token:Option<&str>,asset:&SqliteOriginalLegacyAsset,permitted:bool)->anyhow::Result<()>{let route=format!("/api/v1/files/{}",asset.path.split('/').map(|v|urlencoding::encode(v).into_owned()).collect::<Vec<_>>().join("/"));let mut request=client.get(format!("http://{address}{route}"));if let Some(token)=token{request=request.bearer_auth(token);}let mut response=request.send().await?;if !permitted{anyhow::ensure!(matches!(response.status().as_u16(),401|403|404),"Denied audience retrieved original private legacy bytes");return Ok(());}anyhow::ensure!(response.status()==reqwest::StatusCode::OK,"Actual original legacy route refused");anyhow::ensure!(response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|v|v.to_str().ok())==Some(asset.mime.as_str()),"Original legacy media type differs");let mut offset=0u64;let mut hash=sha2::Sha256::new();let mut bytes=[0u8;65536];while let Some(chunk)=response.chunk().await?{anyhow::ensure!(offset.checked_add(chunk.len()as u64).is_some_and(|n|n<=asset.length),"Actual legacy bytes exceed original bound");for part in chunk.chunks(bytes.len()){anyhow::ensure!(physical_stamp(&asset.held)?==asset.stamp,"Original legacy held bytes changed");asset.held.read_exact_at(&mut bytes[..part.len()],offset)?;anyhow::ensure!(part==&bytes[..part.len()],"Actual legacy bytes retargeted");hash.update(part);offset+=part.len()as u64;}}anyhow::ensure!(offset==asset.length&&hex::encode(hash.finalize())==asset.sha,"Actual legacy length/SHA differs");Ok(())}
#[cfg(test)]mod sqlite_legacy_observation_controls{use super::*;#[test]fn exact_legacy_namespaces_cannot_grant_native_or_alias_authority(){let id="11111111-2222-4333-8444-555555555555";let name=format!("{id}.bin");let path=format!("spaces/original/attachments/page/{name}");assert!(sqlite_legacy_path(id,"original","page",&name,&path).is_ok());for bad in ["../foreign".into(),format!("{path}suffix"),".attachment-upload-admission/receipt.json".into()]{assert!(sqlite_legacy_path(id,"original","page",&name,&bad).is_err());}assert!(sqlite_legacy_path(id,"foreign","page",&name,&path).is_err());assert!(sqlite_legacy_path(id,"original","other-page",&name,&path).is_err());assert!(sqlite_legacy_path(id,"original","page","same-display-name.bin",&path).is_err());}}
